ion<select name="publish_mode" id="publishMode"><option value="Scheduled">Programmer</option><option value="Now">Publier dès approbation</option></select></label><label id="scheduleField">Date et heure<input type="datetime-local" name="scheduled_at"></label></div></section><section class="targets-editor"><h3>Destinations et adaptations</h3><p>Sélectionnez les pages, puis ajustez le texte propre à chaque réseau.</p><?php foreach($connections as $c):?><label class="target-card" data-client="<?= (int)$c['client_id']?>"><span><input type="checkbox" name="connection_ids[]" value="<?= (int)$c['id']?>"><b><?= $e($providers[$c['provider']]??$c['provider'])?></b> · <?= $e($c['account_label'])?></span><textarea name="variant[<?= $e($c['provider'])?>]" rows="3" placeholder="Laisser vide pour reprendre le contenu maître"></textarea></label><?php endforeach?></section></div><footer><button class="button secondary" type="submit">Enregistrer en brouillon</button><button class="button primary" type="submit" name="submit_approval" value="1">Envoyer en validation</button></footer></form></dialog>
<script src="<?= $e(app_url('/public/assets/social-composer.js?v=1')) ?>"></script><script>(function(){const d=document.getElementById('composeDialog');document.querySelector('[data-open-compose]')?.addEventListener('click',()=>d.showModal());document.querySelector('[data-close-compose]')?.addEventListener('click',()=>d.close());d?.addEventListener('click',e=>{if(e.target===d)d.close()});const client=document.getElementById('publishClient');client?.addEventListener('change',()=>document.querySelectorAll('.target-card').forEach(x=>x.hidden=client.value!==''&&x.dataset.client!==client.value));const mode=document.getElementById('publishMode');mode?.addEventListener('change',()=>document.getElementById('scheduleField').hidden=mode.value==='Now');})();</script>
